import { useState } from "react";
import axios from "axios";

function App() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  const handleSearch = async () => {
    if (!query) return;
    try {
      const res = await axios.get(
        `https://en.wikipedia.org/w/api.php`,
        {
          params: {
            action: "opensearch",
            search: query,
            limit: 5,
            namespace: 0,
            format: "json",
            origin: "*",
          },
        }
      );
      setResults(res.data[1]);
    } catch (err) {
      console.error(err);
    }
  };

  // Predefined suggested topics
  const suggestedTopics = {
    History: [
      "Cave paintings",
      "Indus Valley Civilization",
      "How Islam spread to China",
    ],
    Geography: ["Deep sea exploration", "Amazon rainforest", "Mount Everest"],
    Tech: ["Artificial Intelligence", "Quantum Computing", "CRISPR technology"],
    "Random How-Tos": [
      "How to make candles",
      "How to make dyes from plants",
      "How to play Mahjong",
    ],
  };

  return (
    <div style={{ padding: 40, fontFamily: "Arial, sans-serif" }}>
      <h1>Deep Dive Mindmap</h1>

      {/* Search Bar */}
      <div style={{ marginBottom: 20 }}>
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Type a topic..."
          style={{ padding: 8, width: 300, marginRight: 8 }}
        />
        <button onClick={handleSearch} style={{ padding: 8 }}>
          Search
        </button>
      </div>

      {/* Search Results */}
      {results.length > 0 && (
        <div>
          <h3>Search Results:</h3>
          <ul>
            {results.map((topic) => (
              <li key={topic}>
                <a
                  href={`https://en.wikipedia.org/wiki/${encodeURIComponent(
                    topic
                  )}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {topic}
                </a>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Suggested Topics */}
      <div style={{ marginTop: 40 }}>
        <h3>Suggested Topics:</h3>
        <div style={{ display: "flex", gap: 40 }}>
          {Object.entries(suggestedTopics).map(([category, topics]) => (
            <div key={category}>
              <h4>{category}</h4>
              <ul>
                {topics.map((topic) => (
                  <li key={topic}>
                    <a
                      href={`https://en.wikipedia.org/wiki/${encodeURIComponent(
                        topic
                      )}`}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {topic}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default App;
